import { useControlledState } from '@rc-component/util';
import { useCallback, useEffect } from 'react';
import { useRefFunction } from "../utils";
const useFetchData = (getData, options) => {
  const {
    onRequestError,
    effects,
    manual,
    dataSource,
    defaultDataSource,
    onDataSourceChange
  } = options || {};
  const [entity, setEntityInner] = useControlledState(defaultDataSource, dataSource);
  const setEntity = useCallback(updater => {
    setEntityInner(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      onDataSourceChange?.(next);
      return next;
    });
  }, [onDataSourceChange]);
  const [loading, setLoadingInner] = useControlledState(options?.loading, options?.loading);

  /**
   * 使用 useRefFunction 包装回调，确保引用稳定
   */
  const onLoadingChange = useRefFunction(l => {
    options?.onLoadingChange?.(l);
  });

  /**
   * 包装 setLoading，使用 queueMicrotask 延迟回调调用
   * 避免在渲染阶段调用外部回调导致的 React 警告
   */
  const setLoading = useCallback(updater => {
    setLoadingInner(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      queueMicrotask(() => {
        onLoadingChange(next);
      });
      return next;
    });
  }, [onLoadingChange]);
  const updateDataAndLoading = data => {
    setEntity(data);
    setLoading(false);
  };
  /** 请求数据 */
  const fetchList = async () => {
    if (loading) {
      return;
    }
    setLoading(true);
    try {
      const {
        data,
        success
      } = (await getData()) || {};
      if (success !== false) {
        updateDataAndLoading(data);
      }
    } catch (e) {
      // 如果没有传递这个方法的话，需要把错误抛出去，以免吞掉错误
      if (onRequestError === undefined) throw new Error(e);else onRequestError(e);
      setLoading(false);
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {
    if (manual) {
      return;
    }
    fetchList();
  }, [...(effects || []), manual]);
  return {
    dataSource: entity,
    setDataSource: setEntity,
    loading,
    reload: () => {
      return fetchList();
    }
  };
};
export default useFetchData;